<?php
function beginning_status_label($status){return ['Review'=>'Ready for Submission','Draft'=>'Needs Review','Confirmed'=>'Posted','Successful'=>'Posted','Unsuccessful'=>'Needs Correction','Incomplete'=>'Needs Correction'][$status]??$status;}

// Reviewable Beginning Balance uploads; metadata and prior revisions stay in the same import record.
function beginning_review_batch($id,$lock=false){
 $q=db()->prepare("SELECT * FROM import_batches WHERE id=? AND import_type='Beginning Balance'".($lock?' FOR UPDATE':''));$q->execute([$id]);$b=$q->fetch();if(!$b)throw new Exception('Beginning Balance upload not found.');return $b;
}
function beginning_review_editable($b){return in_array($b['status'],['Unsuccessful','Incomplete','Review','Needs Correction','Partial / With Errors'],true)&&(int)$b['imported_count']===0;}
function beginning_review_revision($b){$m=json_decode($b['result_json']??'[]',true)?:[];return (int)($m['beginning_review']['revision']??0);}
function beginning_review_require($b,$revision){
 if(!can_action('upload_beginning'))throw new Exception('Beginning Balance upload permission required.');
 if(!beginning_review_editable($b))throw new Exception('This upload is already posted or cancelled.');
 if((string)beginning_review_revision($b)!==(string)$revision)throw new Exception('This upload changed. Reopen the latest review.');
}
function beginning_review_validate($rows){
 $errors=[];$lines=[];$seen=[];
 foreach($rows as $row){try{$id=(int)$row['product_id'];$q=db()->prepare('SELECT * FROM products WHERE id=?');$q->execute([$id]);$p=$q->fetch();if(!$p)throw new Exception('Product not found. Check the Master SKU or product description.');if(!(int)$p['active'])throw new Exception($p['master_sku'].' — '.$p['name'].' is inactive. Remove this row or reactivate the product in Product Master.');$qty=whole_number($row['qty'],'Beginning Quantity');if(isset($seen[$id]))throw new Exception('Duplicate Product Master item: '.$p['master_sku']);$seen[$id]=true;$q=db()->prepare('SELECT qty FROM beginning_balances WHERE product_id=?');$q->execute([$id]);$lines[]=['product_id'=>$id,'master_sku'=>$p['master_sku'],'name'=>$p['name'],'old_qty'=>(int)($q->fetchColumn()?:0),'new_qty'=>$qty];}catch(Throwable $e){$errors[]='Row '.($row['row']??'?').': '.$e->getMessage();}}
 if(!$rows&&!$errors)$errors[]='No product rows found.';return [$lines,$errors];
}
function beginning_review_stock_signature($lines){
 $snapshot=[];foreach($lines as $x){$id=$x['product_id'];$platform=[];foreach(['Shopee','Lazada','TikTok'] as $p)$platform[$p]=platform_qty($p,$id);$snapshot[$id]=[$x['old_qty'],stock_row($id),$platform,allocation_percentages($id)];}ksort($snapshot);return hash('sha256',json_encode($snapshot));
}
function beginning_review_event($event,$reason=''){return ['event'=>$event,'at'=>date('Y-m-d H:i:s'),'user_id'=>current_user()['id'],'user_name'=>current_user()['name'],'reason'=>$reason];}
function beginning_review_archive($b,$meta){
 return ['revision'=>beginning_review_revision($b),'filename'=>$b['filename'],'stored_path'=>$b['stored_path'],'status'=>$b['status'],'rows_read'=>$b['rows_read'],'errors'=>json_decode($b['error_json']??'[]',true)?:[],'changes'=>$meta['changes']??[],'archived_at'=>date('Y-m-d H:i:s')];
}
function stage_beginning_review($file,$id=0,$revision=0,$reason=''){
 if(!can_action('upload_beginning'))throw new Exception('Beginning Balance upload permission required.');if(setting('beginning_locked','0')==='1')throw new Exception('Beginning Balance is locked.');
 validate_upload_file($file,['xlsx']);$reason=trim((string)$reason);if($id&&($reason===''||strlen($reason)>1000))throw new Exception('Enter a correction reason (up to 1,000 characters).');
 $rows=[];$parseErrors=[];try{$rows=beginning_file_input($file);}catch(Throwable $e){$parseErrors[]=safe_error_message($e);}
 [$lines,$errors]=beginning_review_validate($rows);if($parseErrors)$errors=$parseErrors;
 $stored=store_upload($file,'beginning','BEGIN');$pdo=db();$pdo->beginTransaction();try{
  $meta=[];$workflow=['revision'=>0,'versions'=>[],'events'=>[]];
  if($id){$b=beginning_review_batch($id,true);beginning_review_require($b,$revision);$meta=json_decode($b['result_json']??'[]',true)?:[];$workflow=array_replace($workflow,$meta['beginning_review']??[]);$workflow['versions'][]=beginning_review_archive($b,$meta);}
  $workflow['revision']++;$workflow['events'][]=beginning_review_event($id?'Corrected file uploaded':'File uploaded',$reason);$workflow['rows']=$rows;$workflow['stock_signature']=beginning_review_stock_signature($lines);
  $meta['changes']=$lines;$meta['beginning_review']=$workflow;$status=$errors?'Unsuccessful':'Review';$values=[basename($file['name']),$stored,count($rows),$errors?0:array_sum(array_column($lines,'new_qty')),count($errors),json_encode($errors),json_encode($meta),$status];
  if($id){$pdo->prepare('UPDATE import_batches SET filename=?,stored_path=?,rows_read=?,units=?,error_count=?,error_json=?,result_json=?,status=?,imported_count=0,unmapped_count=0,duplicate_count=0 WHERE id=?')->execute([...$values,$id]);}
  else{$pdo->prepare("INSERT INTO import_batches(filename,stored_path,rows_read,units,error_count,error_json,result_json,status,import_type,user_id) VALUES(?,?,?,?,?,?,?,?,'Beginning Balance',?)")->execute([...$values,current_user()['id']]);$id=(int)$pdo->lastInsertId();}
  audit('Review beginning balance upload','Import',(string)$id,($errors?'Needs correction':'Ready for review').'; revision '.$workflow['revision'].'; '.$reason.'; no balances changed');$pdo->commit();return [$id,$errors];
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function cancel_beginning_review($id,$revision,$reason){
 $reason=trim((string)$reason);if($reason===''||strlen($reason)>1000)throw new Exception('Enter a cancellation reason (up to 1,000 characters).');$pdo=db();$pdo->beginTransaction();try{$b=beginning_review_batch($id,true);beginning_review_require($b,$revision);$meta=json_decode($b['result_json']??'[]',true)?:[];$w=$meta['beginning_review']??['revision'=>0,'versions'=>[],'events'=>[]];$w['revision']++;$w['events'][]=beginning_review_event('Upload cancelled',$reason);$meta['beginning_review']=$w;$pdo->prepare("UPDATE import_batches SET status='Cancelled',result_json=? WHERE id=?")->execute([json_encode($meta),$id]);audit('Cancel beginning balance upload','Import',(string)$id,$reason.'; no balances changed');$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function confirm_beginning_review($id,$revision,$ack){
 if(!$ack)throw new Exception('Confirm that you reviewed the products and quantities.');if(setting('beginning_locked','0')==='1')throw new Exception('Beginning Balance is locked.');require_open_inventory_date(date('Y-m-d'));
 $pdo=db();$pdo->beginTransaction();try{$b=beginning_review_batch($id,true);beginning_review_require($b,$revision);$meta=json_decode($b['result_json']??'[]',true)?:[];$w=$meta['beginning_review']??[];if($b['status']!=='Review'||!isset($w['rows'])||(int)$b['error_count'])throw new Exception('Upload and validate a corrected file before confirming.');
  [$lines,$errors]=beginning_review_validate($w['rows']);if($errors)throw new Exception(implode(' ',array_slice($errors,0,5)));if(!hash_equals($w['stock_signature']??'',beginning_review_stock_signature($lines)))throw new Exception('Stock balances or allocation rules changed after validation. Replace / re-upload the file to review the latest balances.');
  foreach($lines as &$line){$idp=$line['product_id'];check_platform_alignment($idp);$pdo->prepare('INSERT INTO beginning_balances(product_id,qty,updated_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE qty=VALUES(qty),updated_by=VALUES(updated_by)')->execute([$idp,$line['new_qty'],current_user()['id']]);allocate_stock_delta($idp,$line['new_qty']-$line['old_qty'],'Beginning Balance',date('Y-m-d'));validate_allocation_total($idp);$line['platform_balances']=[];foreach(['Shopee','Lazada','TikTok'] as $p)$line['platform_balances'][$p]=platform_qty($p,$idp);}unset($line);
  $w['revision']++;$w['events'][]=beginning_review_event('Beginning Balance submitted and posted');$meta['changes']=$lines;$meta['beginning_review']=$w;$pdo->prepare("UPDATE import_batches SET status='Confirmed',imported_count=?,units=?,result_json=? WHERE id=?")->execute([count($lines),array_sum(array_column($lines,'new_qty')),json_encode($meta),$id]);audit('Confirm beginning balance upload','Import',(string)$id,count($lines).' balances applied; revision '.$w['revision']);$pdo->commit();
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function beginning_review_version_download($id,$version){
 $b=beginning_review_batch($id);$m=json_decode($b['result_json']??'[]',true)?:[];$v=$m['beginning_review']['versions'][$version]??null;if(!$v||!$v['stored_path']){http_response_code(404);exit('Original revision file unavailable.');}$p=realpath(__DIR__.'/'.$v['stored_path']);$root=realpath(__DIR__.'/uploads');if(!$p||!$root||!str_starts_with(strtolower(str_replace('\\','/',$p)),strtolower(str_replace('\\','/',$root)).'/')||!is_file($p)){http_response_code(404);exit('Original revision file unavailable.');}header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.str_replace('"','',basename($v['filename'])).'"');readfile($p);exit;
}
function beginning_review_page($id){
 try{$b=beginning_review_batch($id);}catch(Throwable $e){echo '<div class="alert danger">'.e($e->getMessage()).'</div>';return;}$m=json_decode($b['result_json']??'[]',true)?:[];$w=$m['beginning_review']??[];$errors=json_decode($b['error_json']??'[]',true)?:[];$revision=beginning_review_revision($b);$editable=beginning_review_editable($b)&&can_action('upload_beginning');$locked=setting('beginning_locked','0')==='1';$hidden='<input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="return" value="import_detail&id='.$id.'"><input type="hidden" name="batch_id" value="'.$id.'"><input type="hidden" name="revision" value="'.$revision.'">';
 echo '<div class="page-head"><div><a class="back" href="?page=imports">← Import History</a><h1>Beginning Balance Review</h1><p>Batch #'.$id.' · '.e($b['filename']).' · Revision '.$revision.'</p></div><div class="page-actions">'.badge(beginning_status_label($b['status']),status_badge_class($b['status'])).($b['stored_path']?'<a class="btn ghost" href="download.php?type=original_import&id='.$id.'">Download Current File</a>':'').'</div></div>';
 echo '<div class="alert '.($b['status']==='Confirmed'?'success':'info').'">'.($b['status']==='Confirmed'?'This upload was posted. Corrections must use the inventory adjustment process.':($b['status']==='Cancelled'?'This upload is cancelled. No balances were changed by this upload.':'Review the validation results and quantities, then select Submit & Apply. Your submission posts the balances immediately; no separate draft step or lock is required.')).'</div>';
 echo '<div class="mini-kpis"><div><span>Rows</span><strong>'.(int)$b['rows_read'].'</strong></div><div><span>Proposed Units</span><strong>'.(int)$b['units'].'</strong></div><div><span>Posted Rows</span><strong>'.(int)$b['imported_count'].'</strong></div><div><span>Errors</span><strong>'.count($errors).'</strong></div></div>';
 if($editable){echo '<div class="grid two">';if(!$locked)echo '<div class="card"><h3>Correct / Replace File</h3><p>Upload the corrected XLSX. Previous files and validation errors remain in this record.</p><form method="post" enctype="multipart/form-data" action="actions.php" class="stack">'.$hidden.'<input type="hidden" name="action" value="replace_beginning_upload"><label>Corrected file<input type="file" name="file" accept=".xlsx" required></label><label>Correction reason<textarea name="reason" maxlength="1000" required></textarea></label><button class="btn secondary">Validate Corrected File</button></form></div>';else echo '<div class="card"><h3>Beginning Balance is locked</h3><p>You can cancel this unposted upload. Posted balances require an inventory adjustment.</p></div>';
 echo '<div class="card"><h3>Cancel Upload</h3><p>Close this unposted upload and retain its history.</p><form method="post" action="actions.php" class="stack" data-confirm="Cancel this Beginning Balance upload? No stocks will change.">'.$hidden.'<input type="hidden" name="action" value="cancel_beginning_upload"><label>Cancellation reason<textarea name="reason" maxlength="1000" required></textarea></label><button class="btn danger">Cancel Upload</button></form></div></div>';}
 if($errors){echo '<div class="card table-wrap"><h3>Error Validation Report</h3><table class="table"><tr><th>#</th><th>Details</th></tr>';foreach($errors as $i=>$er)echo '<tr><td>'.($i+1).'</td><td>'.e(is_array($er)?json_encode($er):(string)$er).'</td></tr>';echo '</table><a class="btn ghost" href="download.php?type=import_errors&id='.$id.'">Download Error Report</a></div>';}
 echo '<div class="card table-wrap"><h3>'.($b['status']==='Confirmed'?'Applied':'Proposed').' Beginning Balances</h3><table class="table"><tr><th>Master SKU</th><th>Product</th><th>Previous Beginning</th><th>New Beginning</th><th>Difference</th></tr>';foreach($m['changes']??[] as $c)echo '<tr><td>'.e($c['master_sku']).'</td><td>'.e($c['name']).'</td><td>'.(int)$c['old_qty'].'</td><td>'.(int)$c['new_qty'].'</td><td>'.((int)$c['new_qty']-(int)$c['old_qty']).'</td></tr>';echo '</table>';
 if($editable&&!$locked&&$b['status']==='Review'&&!$errors&&isset($w['rows']))echo '<form method="post" action="actions.php" class="stack" data-confirm="Apply these reviewed Beginning Balances and update platform allocations?">'.$hidden.'<input type="hidden" name="action" value="confirm_beginning_upload"><label class="ack"><input type="checkbox" name="review_ack" value="1" required> I reviewed the products and quantities.</label><button class="btn primary">Submit & Apply Beginning Balance</button></form>';echo '</div>';
 echo '<div class="card table-wrap"><h3>Correction & Cancellation History</h3><table class="table"><tr><th>Date</th><th>Action</th><th>Processed By</th><th>Reason</th></tr>';echo '<tr><td>'.e($b['created_at']).'</td><td>Original upload recorded</td><td>See original processor in Import History</td><td>Batch #'.$id.'</td></tr>';foreach($w['events']??[] as $event)echo '<tr><td>'.e($event['at']).'</td><td>'.e($event['event']).'</td><td>'.e($event['user_name']).'</td><td>'.e($event['reason']).'</td></tr>';echo '</table></div>';
 foreach($w['versions']??[] as $n=>$v){echo '<details class="card"><summary>Previous revision '.(int)$v['revision'].' · '.e($v['filename']).' · '.e($v['status']).'</summary><p>Archived '.e($v['archived_at']).'</p>';if($v['stored_path'])echo '<a class="btn ghost" href="download.php?type=beginning_revision&id='.$id.'&version='.$n.'">Download This Revision</a>';foreach($v['errors'] as $er)echo '<p class="small">'.e(is_array($er)?json_encode($er):$er).'</p>';echo '</details>';}
}
